import { health } from '../api/client.js';

// The status mark: one glyph grammar for every state in pulse.
// Shape + word always carry the meaning; colour only reinforces it.
// Unknown is a hollow dashed ring, never green.
const GLYPHS = {
  ok:      '<circle cx="8" cy="8" r="7" fill="currentColor"/><path d="M4.8 8.2l2.2 2.2 4.2-4.6" fill="none" stroke="var(--on-status)" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>',
  fail:    '<circle cx="8" cy="8" r="7" fill="currentColor"/><path d="M5.5 5.5l5 5M10.5 5.5l-5 5" stroke="var(--on-status)" stroke-width="1.8" stroke-linecap="round"/>',
  unknown: '<circle cx="8" cy="8" r="6.2" fill="none" stroke="currentColor" stroke-width="1.6" stroke-dasharray="3 2.4"/>',
};

export function mark(kind, label) {
  return `<span class="mark mark--${kind}"><svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true">${GLYPHS[kind]}</svg><span>${label}</span></span>`;
}

// ponytail: re-probe on a fixed 30s timer; switch to SSE/websocket when the API grows one.
const PROBE_MS = 30_000;

const STATES = {
  checking: () => mark('unknown', 'Checking API'),
  ok:       () => mark('ok', 'API connected'),
  down:     () => mark('fail', 'API unreachable'),
};

export function renderBadge() {
  return `<div class="conn" role="status" aria-live="polite">
    <span id="conn-state">${STATES.checking()}</span>
    <span class="conn__time" id="conn-time"></span>
  </div>`;
}

// Connected only when /api/health answers with JSON. Anything else is reported as down.
export function startHealthProbe() {
  const state = document.querySelector('#conn-state');
  const time = document.querySelector('#conn-time');
  const fmt = new Intl.DateTimeFormat(undefined, { hour: '2-digit', minute: '2-digit' });
  let last;

  const probe = async () => {
    let next;
    try { await health(); next = 'ok'; } catch { next = 'down'; }
    // Only rewrite the live region when the state changes, so screen readers aren't spammed every 30s.
    if (next !== last) { state.innerHTML = STATES[next](); last = next; }
    time.textContent = `checked ${fmt.format(new Date())}`;
  };

  probe();
  setInterval(probe, PROBE_MS);
}

