import { renderBadge, startHealthProbe, mark } from './components/StatusBadge.js';

// Sample runs. Nothing behind them yet: the runs API is a separate ticket.
// The UI labels this as sample data rather than passing it off as live.
const RUNS = [
  { id: 'r-1041', service: 'checkout', status: 'passed', started: '09:12', duration: '2m 41s' },
  { id: 'r-1040', service: 'billing',  status: 'failed', started: '08:58', duration: '1m 07s' },
  { id: 'r-1039', service: 'catalog',  status: 'passed', started: '08:31', duration: '3m 22s' },
  { id: 'r-1038', service: 'notify',   status: 'passed', started: '08:04', duration: '0m 51s' },
];

// Run data will come from the API one day; never put it into innerHTML raw.
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);

const STATUS = {
  passed: () => mark('ok', 'Passed'),
  failed: () => mark('fail', 'Failed'),
};
const statusMark = (s) => (STATUS[s] ?? (() => mark('unknown', esc(s))))();

// Retry and New run stay visible but inert until the endpoints exist.
// aria-disabled (not disabled) keeps them focusable so the reason is reachable by keyboard.
const OFF = 'aria-disabled="true" aria-describedby="actions-note"';

function row(r) {
  return `<tr class="${r.status === 'failed' ? 'is-failed' : ''}">
    <th scope="row" class="id">${esc(r.id)}</th>
    <td>${esc(r.service)}</td>
    <td>${statusMark(r.status)}</td>
    <td class="num">${esc(r.started)}</td>
    <td class="num">${esc(r.duration)}</td>
    <td class="act">${r.status === 'failed'
      ? `<button class="btn btn--quiet" data-run="${esc(r.id)}" ${OFF} aria-label="Retry ${esc(r.id)}">Retry</button>`
      : ''}</td>
  </tr>`;
}

function summary(runs) {
  if (!runs.length) return '';
  const failed = runs.filter((r) => r.status === 'failed');
  if (!failed.length) return `<p class="summary">${mark('ok', `All ${runs.length} runs passed.`)}</p>`;
  const names = failed.map((r) => esc(r.service)).join(', ');
  return `<p class="summary summary--fail">${mark('fail', `${failed.length} of ${runs.length} runs failed: ${names}.`)}</p>`;
}

function table(runs) {
  if (!runs.length) {
    return `<div class="empty">${mark('unknown', 'No runs yet.')}<p>Runs show up here as soon as a deploy starts.</p></div>`;
  }
  return `<div class="scroll" role="region" aria-labelledby="runs-title" tabindex="0">
    <table>
      <caption class="sr-only">Deploy runs, newest first</caption>
      <thead><tr>
        <th scope="col">Run</th><th scope="col">Service</th><th scope="col">Status</th>
        <th scope="col" class="num">Started</th><th scope="col" class="num">Duration</th>
        <th scope="col" class="act"><span class="sr-only">Actions</span></th>
      </tr></thead>
      <tbody>${runs.map(row).join('')}</tbody>
    </table>
  </div>`;
}

export function render(runs = RUNS) {
  document.querySelector('#app').innerHTML = `
    <header class="top">
      <div class="brand"><span class="wordmark">pulse</span><span class="sub">Deploy runs</span></div>
      ${renderBadge()}
    </header>
    <main class="page">
      <div class="head">
        <h1 id="runs-title">Today</h1>
        <button class="btn btn--primary" id="new-run" ${OFF}>New run</button>
      </div>
      ${summary(runs)}
      ${table(runs)}
      <p class="note" id="actions-note">${mark('unknown', 'Sample data.')} Retry and New run are switched off until the runs API is live.</p>
    </main>`;

  // Inert on purpose: an aria-disabled button must not act. Nothing to wire until the API exists.
  startHealthProbe();
}

render();

