:root {
  color-scheme: light dark;
  --bg:        light-dark(oklch(0.975 0.004 250), oklch(0.17 0.010 250));
  --surface:   light-dark(oklch(1 0 0),           oklch(0.21 0.012 250));
  --ink:       light-dark(oklch(0.22 0.015 250),  oklch(0.94 0.006 250));
  --muted:     light-dark(oklch(0.47 0.015 250),  oklch(0.74 0.012 250));
  --line:      light-dark(oklch(0.91 0.006 250),  oklch(0.30 0.012 250));
  --edge:      light-dark(oklch(0.58 0.015 250),  oklch(0.58 0.015 250)); /* control borders, >=3:1 */
  --accent:    light-dark(oklch(0.50 0.15 255),   oklch(0.74 0.12 255));
  --on-accent: light-dark(oklch(0.99 0 0),        oklch(0.17 0.010 250));
  --ok:        light-dark(oklch(0.50 0.12 150),   oklch(0.76 0.14 150));
  --fail:      light-dark(oklch(0.52 0.19 25),    oklch(0.72 0.16 25));
  --fail-wash: light-dark(oklch(0.97 0.02 25),    oklch(0.24 0.04 25));
  --on-status: var(--surface);
  --ring:      var(--accent);
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas, monospace;
