* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--ink); }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* Top bar */
.top {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 16px;
  padding-block: 12px; padding-inline: 24px;
  background: var(--surface); border-block-end: 1px solid var(--line);
}
.brand { display: flex; align-items: baseline; gap: 12px; }
.wordmark { font-weight: 700; font-size: 1rem; letter-spacing: -0.01em; }
.sub { color: var(--muted); }
.conn { display: flex; align-items: center; gap: 12px; }
.conn__time { color: var(--muted); font-variant-numeric: tabular-nums; }

/* Page */
.page { max-width: 1120px; margin-inline: auto; padding: 24px; }
.head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; }
h1 { margin: 0; font-size: 1.25rem; font-weight: 600; letter-spacing: -0.01em; }

/* The status mark: shape + word, colour reinforces */
.mark { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
.mark svg { flex: none; }
.mark--ok svg      { color: var(--ok); }
.mark--fail svg    { color: var(--fail); }
.mark--unknown svg { color: var(--muted); }
.mark--fail > span { font-weight: 600; }

.summary { margin: 12px 0 16px; }
.summary .mark { white-space: normal; }
.summary--fail { color: var(--ink); }

