.scroll { overflow-x: auto; background: var(--surface); border: 1px solid var(--line); border-radius: 8px; }
table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
th, td { padding: 0 16px; height: 44px; text-align: start; white-space: nowrap; border-block-end: 1px solid var(--line); }
thead th { height: 36px; font-weight: 500; color: var(--muted); background: var(--surface); position: sticky; top: 0; }
tbody tr:last-child > * { border-block-end: 0; }
tbody tr:hover { background: color-mix(in oklch, var(--line) 45%, transparent); }
tbody tr.is-failed { background: var(--fail-wash); }
th.id { font: 500 0.8125rem var(--mono); }
.num { text-align: end; }
.act { width: 1%; text-align: end; }

/* Buttons: one component, two weights */
.btn {
  font: inherit; font-weight: 500; min-height: 32px; padding: 0 14px; border-radius: 6px;
  border: 1px solid var(--edge); background: var(--surface); color: var(--ink); cursor: pointer;
  transition: background-color 150ms ease-out, border-color 150ms ease-out;
}
.btn--primary { background: var(--accent); border-color: var(--accent); color: var(--on-accent); }
.btn:hover:not([aria-disabled="true"]) { background: color-mix(in oklch, var(--surface) 88%, var(--ink)); }
.btn--primary:hover:not([aria-disabled="true"]) { background: color-mix(in oklch, var(--accent) 88%, var(--ink)); }
.btn[aria-disabled="true"] {
  cursor: not-allowed; background: transparent; color: var(--muted);
  border-color: var(--edge); border-style: dashed; /* dashed = not live, same grammar as the unknown ring */
}
:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; border-radius: 4px; }
.scroll:focus-visible { outline-offset: 0; }

/* Empty + note */
.empty { padding: 40px 24px; text-align: center; background: var(--surface); border: 1px solid var(--line); border-radius: 8px; }
.empty p { margin: 8px 0 0; color: var(--muted); }
.note { margin: 12px 0 0; color: var(--muted); }
.note .mark { color: var(--ink); }

/* Only the checking ring moves; the word "Checking" carries the state without it. */
@media (prefers-reduced-motion: no-preference) {
  .conn .mark--unknown svg { animation: spin 1.6s linear infinite; }
}
@keyframes spin { to { rotate: 360deg; } }

